mapper.select:
SELECT COALESCE(expires_at, '')
FROM document_share
WHERE attachment_id = #{attachmentId} AND to_employee_id = #{toId}

SELECT COUNT(*)
FROM document_folder
WHERE name = #{name}
  AND parent_id IS NOT DISTINCT FROM #{parentId, jdbcType=BIGINT}
  AND id <> #{excludeId}

mapper.update:
UPDATE document_folder
   SET lock_hash = #{lockHash, jdbcType=VARCHAR}, lock_by = #{lockBy, jdbcType=VARCHAR}, lock_at = #{lockAt, jdbcType=VARCHAR}
 WHERE id = #{id}
